// --- CONFIGURAÇÃO DO SUPABASE ---
const SUPABASE_URL = "https://dzfamogbogonwxgdpvbl.supabase.co";
const SUPABASE_KEY = "SUA_CHAVE_PUBLISHABLE_COPIADA_AQUI";

const supabase = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY);

// Função para calcular minutos de espera no painel
function calcularMinutosEspera(horaCriacaoMs) {
    if (!horaCriacaoMs) return 0;
        const agora = Date.now();
            return Math.max(0, Math.floor((agora - horaCriacaoMs) / 60000));
            }

            // --- PÁGINA DO AGENTE (FORMULÁRIO - index.html) ---
            const formAtendimento = document.getElementById('formAtendimento');
            if (formAtendimento) {
                const btnAssumir = document.getElementById('btnAssumir');
                    const btnPendente = document.getElementById('btnPendente');

                        function capturarDadosFormulario() {
                                return {
                                            passageiro: document.getElementById('passageiro').value.trim(),
                                                        servico: document.getElementById('servico').value,
                                                                    voo: document.getElementById('voo').value.trim().toUpperCase(),
                                                                                origem: document.getElementById('origem').value.trim().toUpperCase(),
                                                                                            destino: document.getElementById('destino').value.trim().toUpperCase(),
                                                                                                        timestamp: Date.now()
                                                                                                                };
                                                                                                                    }

                                                                                                                        function validarFormulario(dados) {
                                                                                                                                if (!dados.passageiro || !dados.servico || !dados.voo || !dados.origem || !dados.destino) {
                                                                                                                                            alert('Por favor, preencha todos os campos do formulário.');
                                                                                                                                                        return false;
                                                                                                                                                                }
                                                                                                                                                                        return true;
                                                                                                                                                                            }

                                                                                                                                                                                // Ação do botão "Assumir Agora"
                                                                                                                                                                                    if (btnAssumir) {
                                                                                                                                                                                            btnAssumir.addEventListener('click', async () => {
                                                                                                                                                                                                        const dados = capturarDadosFormulario();
                                                                                                                                                                                                                    if (!validarFormulario(dados)) return;

                                                                                                                                                                                                                                const agente = prompt("Digite o seu nome (Agente):");
                                                                                                                                                                                                                                            if (!agente) return;

                                                                                                                                                                                                                                                        dados.status = "Em Andamento";
                                                                                                                                                                                                                                                                    dados.agente = agente;
                                                                                                                                                                                                                                                                                dados.hora_inicio = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

                                                                                                                                                                                                                                                                                            const { error } = await supabase.from('atendimentos').insert([dados]);
                                                                                                                                                                                                                                                                                                        if (error) {
                                                                                                                                                                                                                                                                                                                        console.error("Erro Supabase:", error);
                                                                                                                                                                                                                                                                                                                                        alert("Erro ao salvar o atendimento no banco.");
                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                    alert("Atendimento assumido com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                    formAtendimento.reset();
                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                // Ação do botão "Deixar Pendente"
                                                                                                                                                                                                                                                                                                                                                                                                                    if (btnPendente) {
                                                                                                                                                                                                                                                                                                                                                                                                                            btnPendente.addEventListener('click', async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                        const dados = capturarDadosFormulario();
                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!validarFormulario(dados)) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                dados.status = "Pendente";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dados.agente = "Aguardando Agente";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dados.hora_inicio = "-";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const { error } = await supabase.from('atendimentos').insert([dados]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.error("Erro Supabase:", error);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Erro ao salvar o atendimento no banco.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Atendimento registrado como PENDENTE!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formAtendimento.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // --- PÁGINA DE CONTROLE / PAINEL (controle.html) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const listaAtivos = document.getElementById('listaAtivos');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (listaAtivos) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        async function carregarAtendimentos() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const { data: lista, error } = await supabase
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .from('atendimentos')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .select('*')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .order('timestamp', { ascending: false });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.error("Erro ao carregar painel:", error);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listaAtivos.innerHTML = '';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!lista || lista.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listaAtivos.innerHTML = '<p class="vazio">Nenhum atendimento registrado no momento.</p>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    lista.forEach(item => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const minutosEspera = item.status === 'Pendente' ? calcularMinutosEspera(item.timestamp) : 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const card = document.createElement('div');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        card.className = `card-atendimento ${item.status === 'Pendente' ? 'card-pendente' : 'card-em-andamento'}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    card.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="card-header">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <strong>${item.passageiro}</strong>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span class="badge ${item.status === 'Pendente' ? 'badge-pendente' : 'badge-andamento'}">${item.status}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="card-body">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p><strong>Voo:</strong> ${item.voo} | <strong>Rota:</strong> ${item.origem} ➔ ${item.destino}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p><strong>Serviço:</strong> ${item.servico}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p><strong>Agente:</strong> ${item.agente}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ${item.status === 'Pendente' 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ? `<p class="timer-alerta">⏳ Esperando há: <strong>${minutosEspera} min</strong></p>` 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : `<p><strong>Início:</strong> ${item.hora_inicio}</p>`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ${item.status === 'Pendente' ? `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div class="card-footer">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button onclick="assumirPendente('${item.id}')" class="btn-assumir-card">Assumir Atendimento</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ` : ''}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listaAtivos.appendChild(card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Função global para assumir um atendimento pendente direto pelo painel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        window.assumirPendente = async function(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const agente = prompt("Digite seu nome para assumir este atendimento:");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!agente) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const hora_inicio = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { error } = await supabase
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .from('atendimentos')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .update({ status: 'Em Andamento', agente: agente, hora_inicio: hora_inicio })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .eq('id', id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Erro ao assumir atendimento.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.error(error);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                carregarAtendimentos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Carrega na abertura e atualiza a cada 5 segundos
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    carregarAtendimentos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setInterval(carregarAtendimentos, 5000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        